```sql
/* Buffets and coffee shops open between 07:30 and 16:00 */
SELECT
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE (
        LOWER(r."service_format") LIKE '%buffet%'
        OR LOWER(r."service_format") LIKE '%coffee%'
        OR LOWER(r."name") LIKE '%buffet%'
        OR LOWER(r."name") LIKE '%coffee%'
      )
  /* Ensure the opening time is at or before 07:30 and closing time at or after 16:00 */
  AND (
        /* Extract opening and closing times from the hours text and compare */
        (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1] IS NOT NULL
      )
  AND (
        /* Opening time <= 07:30 */
        (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1]::time <= TIME '07:30'
      )
  AND (
        /* Closing time >= 16:00 (second time found in the string) */
        (regexp_match(r."hours", '(\d{1,2}:\d{2}).*?(\d{1,2}:\d{2})'))[2]::time >= TIME '16:00'
      )
ORDER BY r."name";
```

```sql
/* Находим системы (название и статус активности), которые назначены всем IT-специалистам поддержки */
SELECT
    s."system_name",
    s."is_active"
FROM "systems" AS s
JOIN "it_support_specialists_systems" AS iss ON iss."system_id" = s."system_id"
GROUP BY s."system_id", s."system_name", s."is_active"
HAVING COUNT(DISTINCT iss."it_specialist_id") = (
    /* Общее количество IT-специалистов поддержки */
    SELECT COUNT(DISTINCT "id") FROM "it_support_specialists"
);
```

